cuda_source = r'''
#include <torch/extension.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

extern "C"
__global__ void gemm_fp16_naive(const half* __restrict__ A,
                                const half* __restrict__ B,
                                half* __restrict__ C,
                                const int M,
                                const int N,
                                const int K) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = M * N;
    if (idx >= total) return;

    int row = idx / N;
    int col = idx % N;

    float acc = 0.0f;
    for (int k = 0; k < K; ++k) {
        half a = A[row * K + k];
        half b = B[k * N + col];
        acc += __half2float(a) * __half2float(b);
    }
    C[row * N + col] = __float2half(acc);
}
'''

# Build the inline extension
gemm_module = load_inline(
    name='gemm_fp16_inline',
    sources=[],
    cuda_sources=cuda_source,
    functions=['gemm_fp16_naive'],
    verbose=False,
