    C = torch.empty((M, N), dtype=torch.float16, device=A.device)

    threads_per_block = 256
    total_elements = M * N
    blocks = (total_elements + threads_per_block - 1) // threads_per_block

    gemm_module.gemm_fp16_naive(
        A,
        B,
        C,
        M,
        N,
        K,
        grid=(blocks,),
        block=(threads_per_block,),
    )
    return C

